const item = $input.first().json;
const body = item.body || item;

const type = body.type;
if (type !== 'demo' && type !== 'rueckruf' && type !== 'kundentermin') {
  return [{ json: { mode: 'error', message: 'Ungültiger Typ (demo, rueckruf oder kundentermin)' } }];
}

const defaultDuration = type === 'rueckruf' ? 5 : 15;
let duration = parseInt(body.duration_minutes, 10);
if (!duration || duration < 1) duration = defaultDuration;
const allowed = type === 'rueckruf' ? [5] : [15];
if (allowed.indexOf(duration) < 0) {
  return [{ json: { mode: 'error', message: 'Ungültige Dauer (Rückruf: 5 Min, Demo/Kundentermin: 15 Min)' } }];
}

const startStr = body.start;
if (!startStr) {
  return [{ json: { mode: 'error', message: 'Startzeit fehlt' } }];
}

const start = new Date(startStr);
if (isNaN(start.getTime())) {
  return [{ json: { mode: 'error', message: 'Ungültige Startzeit' } }];
}

const end = new Date(start.getTime() + duration * 60000);

const firma = body.firma || 'Unbekannt';
const kontakt = body.kontakt || '—';
const email = body.email || '—';
const telefon = body.telefon || '—';
const website = body.website || '—';
const notiz = (body.notiz || '').trim();
const contactId = body.contact_id || '';

const summary = type === 'demo' ? 'Demo: ' + firma : type === 'kundentermin' ? 'Kundentermin: ' + firma : 'Rückruf: ' + firma;
const lines = [
  'Firma: ' + firma,
  'Ansprechpartner: ' + kontakt,
  'E-Mail: ' + email,
  'Telefon: ' + telefon,
  'Website: ' + website
];
if (notiz) lines.push('Notiz: ' + notiz);
if (contactId) lines.push('CRM-ID: ' + contactId);
lines.push('');
if (type === 'demo') {
  lines.push('Kunden-Einladung separat von kevin@ritz-ai.solutions per E-Mail senden.');
} else if (type === 'kundentermin') {
  lines.push('Kundentermin im internen Kalender (ritzaisolutions@gmail.com).');
} else {
  lines.push('Interner Rückruf-Termin (ritzaisolutions@gmail.com).');
}

return [{
  json: {
    mode: 'create',
    summary,
    description: lines.join('\n'),
    start: start.toISOString(),
    end: end.toISOString(),
    contact_id: contactId,
    cal_type: type
  }
}];
